INSERT INTO `blogs` VALUES (1,'{\"ar\":\"أهمية التحول الرقمي في القطاع الصحي\",\"en\":\"The Importance of Digital Transformation in Healthcare\"}','{\"ar\":\"نظرة شاملة على كيفية تحسين التقنيات الرقمية لجودة الرعاية الصحية وتسريع تقديم الخدمات للمرضى.\",\"en\":\"A comprehensive look at how digital technologies improve the quality of healthcare and accelerate service delivery.\"}','ahmy-althol-alrkmy-fy-alktaaa-alshy','{\"ar\":\"<p>يشهد القطاع الصحي تحولاً جذرياً بفضل التقنيات الحديثة مثل الذكاء الاصطناعي والتطبيب عن بعد. تسهم هذه التطورات في توفير تشخيصات أدق وتجربة رعاية أفضل للمرضى...</p>\",\"en\":\"The healthcare sector is undergoing a radical transformation thanks to modern technologies like AI and telemedicine. These advancements contribute to more accurate diagnoses and better patient care experiences...\"}','blogs/935491c7-3ea3-41ed-93f3-5a00d2fdf3ae.webp',1,18,1,2768,'published','2026-03-29 03:43:14','2026-04-27 03:43:14','2026-08-29 06:34:43',NULL),(2,'{\"ar\":\"كيف تطور مهاراتك كممارس صحي؟\",\"en\":\"How to Develop Your Skills as a Health Practitioner?\"}','{\"ar\":\"خطوات عملية ونصائح قيمة لتنمية قدراتك المهنية والطبية في عالم يتغير باستمرار.\",\"en\":\"Practical steps and valuable tips to develop your professional and medical capabilities in an ever-changing world.\"}','kyf-ttor-mharatk-kmmars-shy','{\"ar\":\"<p>في ظل التطور المتسارع في المجال الطبي، أصبح التعلم المستمر ضرورة وليس خياراً. التدريب والتأهيل واكتساب المهارات الناعمة مثل التواصل وحل المشكلات تعتبر من أسس النجاح...</p>\",\"en\":\"In light of the rapid development in the medical field, continuous learning has become a necessity, not a luxury. Training, qualification, and acquiring soft skills like communication are foundations of success...\"}','blogs/5945aa1b-0c41-44f4-9ae6-4ecab708c47a.webp',1,2,1,2664,'published','2026-04-25 03:43:14','2026-04-27 03:43:14','2026-09-04 03:34:54',NULL),(3,'{\"ar\":\"أحدث التقنيات في إدارة الأمراض المزمنة\",\"en\":\"Latest Technologies in Chronic Disease Management\"}','{\"ar\":\"تعرف على التطبيقات والأجهزة الذكية التي تساعد المرضى على تتبع حالتهم الصحية يومياً.\",\"en\":\"Learn about smart applications and devices that help patients track their health status daily.\"}','ahdth-altknyat-fy-adar-alamrad-almzmn','{\"ar\":\"<p>إدارة الأمراض المزمنة مثل السكري وضغط الدم أصبحت أكثر سهولة بفضل الأجهزة القابلة للارتداء والتطبيقات الذكية التي ترسل تقارير دورية للأطباء...</p>\",\"en\":\"Managing chronic diseases like diabetes and blood pressure has become much easier thanks to wearable devices and smart apps that send periodic reports to doctors...\"}','blogs/5e332334-1b48-4346-a101-a4cc66c43c09.webp',1,2,1,2429,'published','2026-04-09 03:43:14','2026-04-27 03:43:14','2026-09-04 03:34:53',NULL),(4,'{\"ar\":\"مستقبل التعليم الطبي بعد الجائحة\",\"en\":\"The Future of Medical Education After the Pandemic\"}','{\"ar\":\"دروس مستفادة من الأزمات السابقة وكيف أصبحت المنصات الرقمية أساساً في التأهيل الصحي.\",\"en\":\"Lessons learned from past crises and how digital platforms became a foundation in health qualification.\"}','mstkbl-altaalym-altby-baad-algayh','{\"ar\":\"<p>لقد غيرت الجائحة طريقة تقديم التعليم الطبي. المنصات الرقمية مثل Medvion تقدم الآن محتوى تفاعلياً وشهادات معتمدة تسد الفجوة بين النظري والعملي...</p>\",\"en\":\"The pandemic changed the way medical education is delivered. Digital platforms like Medvion now offer interactive content and accredited certificates bridging the gap between theory and practice...\"}','blogs/3ccdcdfc-3468-4006-a57b-181813cabb6e.webp',1,2,1,3860,'published','2026-04-06 03:43:14','2026-04-27 03:43:14','2026-09-04 03:34:54',NULL),(5,'{\"ar\":\"تجربه\",\"en\":\"\"}','{\"ar\":\".........\",\"en\":\"\"}','tgrbh','{\"ar\":\"<p>...................1</p>\",\"en\":\"\"}','blogs/36c99953-8e3d-4f41-b8b7-6e5c5ff5104d.webp',15,2,NULL,119,'published','2026-05-09 10:22:00','2026-05-09 10:22:35','2026-09-02 16:54:43',NULL);
/*!40000 ALTER TABLE `blogs` ENABLE KEYS */;
UNLOCK TABLES;

