INSERT INTO `faqs` VALUES (1,'{\"ar\":\"هل الدورات معتمدة رسمياً؟\",\"en\":\"Are the courses officially accredited?\"}','{\"ar\":\"نعم، جميع الدورات المقدمة على منصة Medvion معتمدة وتصدر بها شهادات إتمام معترف بها من قِبل الجهات الطبية والأكاديمية المختصة.\",\"en\":\"Yes, all courses offered on the Medvion platform are accredited and come with completion certificates recognised by the relevant medical and academic authorities.\"}',1,1,NULL,NULL,'2026-04-16 11:56:54','2026-04-16 11:56:54',NULL),(2,'{\"ar\":\"هل يمكنني التعلم من أي جهاز ذكي؟\",\"en\":\"Can I learn from any smart device?\"}','{\"ar\":\"بالتأكيد، المنصة مُصممة لتكون متوافقة بالكامل مع الهواتف الذكية والأجهزة اللوحية وأجهزة الكمبيوتر دون أي قيود.\",\"en\":\"Absolutely. The platform is fully responsive and compatible with smartphones, tablets, and computers without any limitations.\"}',2,1,NULL,NULL,'2026-04-16 11:56:54','2026-04-16 11:56:54',NULL),(3,'{\"ar\":\"كيف أحصل على شهادة الإتمام؟\",\"en\":\"How do I receive my completion certificate?\"}','{\"ar\":\"بعد استكمال جميع وحدات الدورة واجتياز الاختبار النهائي بنجاح، ستحصل تلقائياً على شهادة إتمام رقمية موثقة قابلة للمشاركة والطباعة.\",\"en\":\"After completing all course units and passing the final assessment, you will automatically receive a verified digital completion certificate that can be shared and printed.\"}',3,1,NULL,NULL,'2026-04-16 11:56:54','2026-04-16 11:56:54',NULL),(4,'{\"ar\":\"هل هناك رسوم للتسجيل في المنصة؟\",\"en\":\"Are there registration fees?\"}','{\"ar\":\"التسجيل في منصة Medvion مجاني تماماً. بعض الدورات المتخصصة قد تكون مدفوعة، في حين يتوفر عدد كبير من الدورات مجاناً للجميع.\",\"en\":\"Registration on Medvion is completely free. Some specialised courses may be paid, while a large number of courses are available free of charge for everyone.\"}',4,1,NULL,NULL,'2026-04-16 11:56:54','2026-04-16 11:56:54',NULL),(5,'{\"ar\":\"من يؤهل لالتحاق بالدورات؟\",\"en\":\"Who is eligible to enrol in the courses?\"}','{\"ar\":\"الدورات مفتوحة لجميع العاملين في القطاع الصحي، بما في ذلك الأطباء والممرضون والصيادلة وطلاب الكليات الطبية والمهتمون بالتطوير المهني الصحي.\",\"en\":\"Courses are open to all healthcare professionals, including doctors, nurses, pharmacists, medical students, and anyone interested in continuing professional health development.\"}',5,1,NULL,NULL,'2026-04-16 11:56:54','2026-04-16 11:56:54',NULL);
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

