INSERT INTO `goals` VALUES (1,'{\"ar\":\"الهدف 1\",\"en\":\"Goal 1\"}','{\"ar\":\"تطوير مهارات الكوادر الصحية عبر التدريب الرقمي.\",\"en\":\"Developing the skills of healthcare professionals through digital training.\"}',NULL,1,1,NULL,NULL,NULL,NULL,'2026-04-16 11:56:55','2026-04-16 11:56:55'),(2,'{\"ar\":\"الهدف 2\",\"en\":\"Goal 2\"}','{\"ar\":\"نشر المعرفة الطبية الحديثة بين العاملين في القطاع الصحي.\",\"en\":\"Spreading modern medical knowledge among healthcare workers.\"}',NULL,2,1,NULL,NULL,NULL,NULL,'2026-04-16 11:56:55','2026-04-16 11:56:55'),(3,'{\"ar\":\"الهدف 3\",\"en\":\"Goal 3\"}','{\"ar\":\"توفير فرص تدريب مستمر للكوادر الصحية في مختلف التخصصات.\",\"en\":\"Providing continuous training opportunities for healthcare professionals in various specialties.\"}',NULL,3,1,NULL,NULL,NULL,NULL,'2026-04-16 11:56:55','2026-04-16 11:56:55'),(4,'{\"ar\":\"الهدف 4\",\"en\":\"Goal 4\"}','{\"ar\":\"تعزيز ثقافة التعليم الصحي المستمر.\",\"en\":\"Promoting the culture of continuous health education.\"}',NULL,4,1,NULL,NULL,NULL,NULL,'2026-04-16 11:56:55','2026-04-16 11:56:55'),(5,'{\"ar\":\"الهدف 5\",\"en\":\"Goal 5\"}','{\"ar\":\"دعم التحول الرقمي في مجال التعليم الصحي.\",\"en\":\"Supporting digital transformation in health education.\"}',NULL,5,1,NULL,NULL,NULL,NULL,'2026-04-16 11:56:55','2026-04-16 11:56:55');
