INSERT INTO `hero_slides` VALUES (1,'/images/hero-slide-1.png','{\"ar\":\"قريباً • الإطلاق الرسمي\",\"en\":\"Coming Soon • Official Launch\"}','{\"ar\":\"منصتك الأولى نحو\",\"en\":\"Your Premier Destination for\"}','{\"ar\":\"التدريب الصحي الرقمي\",\"en\":\"Digital Health Training\"}','{\"ar\":\"ارتقِ بمسارك المهني في القطاع الصحي عبر برامج تدريبية متخصصة، مُصمَّمة بأعلى معايير الجودة الأكاديمية والمهنية.\",\"en\":\"Advance your professional career in healthcare through specialised training programmes designed to the highest academic and professional quality standards.\"}',1,1,'2026-04-16 11:56:54','2026-04-16 11:56:54'),(2,'/images/hero-slide-2.png','{\"ar\":\"قريباً • الإطلاق الرسمي\",\"en\":\"Coming Soon • Official Launch\"}','{\"ar\":\"محتوى علمي معتمد\",\"en\":\"Accredited Content Meets\"}','{\"ar\":\"بتقنية تعليمية متطورة\",\"en\":\"Cutting-Edge Learning Technology\"}','{\"ar\":\"نُوظِّف أحدث أساليب التعلم الرقمي لنقدم لك تجربة تدريبية استثنائية في أي وقت ومن أي مكان.\",\"en\":\"We harness the latest digital learning methods to deliver an exceptional training experience — accessible anytime, anywhere.\"}',1,2,'2026-04-16 11:56:54','2026-04-16 11:56:54'),(3,'/images/hero-slide-3.png','{\"ar\":\"قريباً • الإطلاق الرسمي\",\"en\":\"Coming Soon • Official Launch\"}','{\"ar\":\"انضم إلى نخبة\",\"en\":\"Join an Elite Community of\"}','{\"ar\":\"المهنيين الصحيين\",\"en\":\"Healthcare Professionals\"}','{\"ar\":\"كن جزءاً من مجتمع من المختصين الصحيين الذين يطوّرون كفاءاتهم ومسيرتهم المهنية مع منصة Medvion.\",\"en\":\"Become part of a network of dedicated health professionals committed to developing their competencies and advancing their careers with Medvion.\"}',1,3,'2026-04-16 11:56:54','2026-04-16 11:56:54');
