INSERT INTO `surveys` VALUES (1,'Medvion Expert Selection Board - برنامج اختيار خبراء التدريب الصحي الرقمي','هذا ليس نموذج تسجيل… بل تقييم انتقائي لاختيار خبراء Medvion\nفي Medvion، يتم اختيار الخبراء بناءً على معايير دقيقة تشمل:\nالكفاءة السريرية / الفنية\nالقدرة على نقل المعرفة بفعالية\nالتفكير التحليلي واتخاذ القرار\nالأثر المهني المتوقع\nيتم قبول نسبة محدودة من المتقدمين.\nسيتم التواصل فقط مع المرشحين المؤهلين.',1,NULL,'2026-04-16 11:56:55','2026-04-16 11:56:55',NULL);
