INSERT INTO `testimonials` VALUES (1,'{\"en\":\"Dr. Ahmed Yassin\",\"ar\":\"د. أحمد ياسين\"}','{\"en\":\"Cardiologist\",\"ar\":\"استشاري أمراض القلب\"}','{\"en\":\"Medvion has completely transformed the way we manage professional training. The content is highly relevant and structured perfectly for busy healthcare professionals.\",\"ar\":\"لقد غيَّرت Medvion تماماً من طريقة إدارتنا للتدريب المهني. المحتوى دقيق جداً ومنظم بطريقة مثالية للممارسين الصحيين.\"}',5,'testimonials/6f1bd196-71a0-4a18-94fe-c49ac4582c6f.webp','active',NULL,'2026-04-27 03:43:05','2026-05-25 01:18:14'),(2,'{\"en\":\"Sarah Al-Qahtani\",\"ar\":\"سارة القحطاني\"}','{\"en\":\"Nursing Student\",\"ar\":\"طالبة تمريض\"}','{\"en\":\"The flexibility of the courses allowed me to learn at my own pace. The interactive modules and quizzes were exceptional in testing my knowledge.\",\"ar\":\"مرونة الدورات التدريبية سمحت لي بالتعلم بالسرعة التي تناسبني. الوحدات التفاعلية والاختبارات كانت استثنائية في تقييم معرفتي.\"}',5,'testimonials/dummy-ldGYZOTa.webp','active',NULL,'2026-04-27 03:43:05','2026-04-27 03:43:05'),(3,'{\"en\":\"Dr. Khalid Al-Otaibi\",\"ar\":\"د. خالد العتيبي\"}','{\"en\":\"General Surgeon\",\"ar\":\"جراح عام\"}','{\"en\":\"I highly recommend Medvion for any medical professional looking to stay updated with the latest in the medical field. Truly a premium experience.\",\"ar\":\"أوصي بشدة بمنصة Medvion لأي ممارس صحي يبحث عن مواكبة أحدث التطورات في المجال الطبي. تجربة فاخرة بكل المقاييس.\"}',4,'testimonials/dummy-slak6MW7.webp','active',NULL,'2026-04-27 03:43:05','2026-04-27 03:43:05'),(4,'{\"en\":\"Nora Abdullah\",\"ar\":\"نورة عبدالله\"}','{\"en\":\"Hospital Administrator\",\"ar\":\"مديرة مستشفى\"}','{\"en\":\"Partnering with Medvion was the best decision for our hospital\'s continuous medical education program. The analytics and reporting are top-notch.\",\"ar\":\"التعاون مع Medvion كان أفضل قرار اتخذناه لبرنامج التعليم الطبي المستمر في مستشفانا. التحليلات والتقارير المقدمة ممتازة.\"}',5,'testimonials/dummy-UCaWiHF3.webp','active',NULL,'2026-04-27 03:43:05','2026-04-27 03:43:05'),(5,'{\"ar\":\"عبدالله \"}','{\"ar\":\"استشاري أمراض القلب\"}','{\"ar\":\"ممتاز جدا\"}',5,'testimonials/1c7d03a1-13c0-4093-aa2d-b41b81c1dcfe.webp','active',NULL,'2026-05-09 10:13:27','2026-05-09 10:13:27');
/*!40000 ALTER TABLE `testimonials` ENABLE KEYS */;
UNLOCK TABLES;

